// A stand-in for the slice of @modelcontextprotocol/sdk the plugin touches,
// laid out at the real paths under the fixture DSH_HOME so the plugin's
// default path derivation resolves it. Records every request so tests assert
// on what actually went over the (pretend) wire. `connect`/`transport` mirror
// the SDK's Protocol surface; transports may carry the stdio server params the
// plugin reads at connect time.

export const requests = []

export const fixtureState = {
  failSessionStart: false
}

export class Client {
  transport = null

  async connect (transport) {
    this.transport = transport
    return {}
  }

  async request (request, resultSchema, options) {
    if (fixtureState.failSessionStart === true && request?.params?.name === 'session_start') {
      throw new Error('stub transport refused')
    }
    requests.push(JSON.parse(JSON.stringify(request)))
    const parsed = resultSchema?.parse !== undefined ? resultSchema.parse({ ok: true }) : { ok: true }
    return parsed
  }
}
